from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel
import secrets
import base64, json, hmac, hashlib, time, os

app = FastAPI()
port = int(os.getenv('PORT', 3000))

SECRET = 'oauth-secret'
auth_codes = {}

def base64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode()

def create_token(payload: dict) -> str:
    header = base64url(json.dumps({'alg': 'HS256', 'typ': 'JWT'}).encode())
    body = base64url(json.dumps(payload).encode())
    signature = base64url(hmac.new(SECRET.encode(), f'{header}.{body}'.encode(), hashlib.sha256).digest())
    return f'{header}.{body}.{signature}'

def verify_token(token: str):
    parts = token.split('.')
    if len(parts) != 3:
        return None
    header, body, signature = parts
    expected_sig = base64url(hmac.new(SECRET.encode(), f'{header}.{body}'.encode(), hashlib.sha256).digest())
    if signature != expected_sig:
        return None
    return json.loads(base64.urlsafe_b64decode(body + '==').decode())

class TokenRequest(BaseModel):
    grant_type: str
    code: str
    client_id: str

@app.get('/oauth/authorize')
def authorize(client_id: str = None):
    if not client_id:
        return {'error': 'Missing client_id'}
    code = secrets.token_hex(16)
    auth_codes[code] = {'client_id': client_id, 'created_at': time.time()}
    return {'code': code}

@app.post('/oauth/token')
def token(body: TokenRequest):
    if body.grant_type != 'authorization_code':
        return {'error': 'Unsupported grant_type'}
    auth_code = auth_codes.get(body.code)
    if not auth_code or auth_code['client_id'] != body.client_id:
        return {'error': 'Invalid code'}
    access_token = create_token({'sub': 'user123', 'client_id': body.client_id, 'iat': int(time.time()), 'exp': int(time.time()) + 3600})
    del auth_codes[body.code]
    return {'access_token': access_token, 'token_type': 'Bearer', 'expires_in': 3600}

@app.get('/oauth/resource')
def resource(request: Request):
    auth_header = request.headers.get('authorization')
    if not auth_header or not auth_header.startswith('Bearer '):
        return JSONResponse(status_code=401, content={'error': 'Unauthorized'})
    token = auth_header.split(' ')[1]
    payload = verify_token(token)
    if not payload:
        return JSONResponse(status_code=401, content={'error': 'Invalid token'})
    return {'userId': payload['sub'], 'client_id': payload['client_id']}

