package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"net/http"
	"os"
	"strings"
	"time"
)

const SECRET = "oauth-secret"

func base64Url(data []byte) string {
	return strings.TrimRight(base64.URLEncoding.EncodeToString(data), "=")
}

func verifyToken(token string) map[string]interface{} {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return nil
	}
	header, body, signature := parts[0], parts[1], parts[2]
	mac := hmac.New(sha256.New, []byte(SECRET))
	mac.Write([]byte(header + "." + body))
	expectedSig := base64Url(mac.Sum(nil))
	if signature != expectedSig {
		return nil
	}
	decodedBody, _ := base64.URLEncoding.WithPadding(base64.NoPadding).DecodeString(body)
	var payload map[string]interface{}
	json.Unmarshal(decodedBody, &payload)
	if exp, ok := payload["exp"].(float64); ok && exp < float64(time.Now().Unix()) {
		return map[string]interface{}{"expired": true}
	}
	return payload
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/oauth/resource", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		authHeader := r.Header.Get("Authorization")
		if !strings.HasPrefix(authHeader, "Bearer ") {
			w.WriteHeader(http.StatusUnauthorized)
			json.NewEncoder(w).Encode(map[string]string{"error": "Unauthorized"})
			return
		}
		token := strings.TrimPrefix(authHeader, "Bearer ")
		result := verifyToken(token)
		if result == nil {
			w.WriteHeader(http.StatusUnauthorized)
			json.NewEncoder(w).Encode(map[string]string{"error": "Invalid token"})
			return
		}
		if _, ok := result["expired"]; ok {
			w.WriteHeader(http.StatusUnauthorized)
			json.NewEncoder(w).Encode(map[string]string{"error": "Token expired"})
			return
		}
		json.NewEncoder(w).Encode(map[string]interface{}{"userId": result["sub"]})
	})

	http.ListenAndServe(":"+port, nil)
}

