package main

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"os"
	"strings"
	"time"
)

const SECRET = "oauth-secret"

var (
	authCodes      = make(map[string]map[string]interface{})
	refreshTokens  = make(map[string]map[string]interface{})
)

func base64Url(data []byte) string {
	return strings.TrimRight(base64.URLEncoding.EncodeToString(data), "=")
}

func createToken(payload map[string]interface{}) string {
	header := base64Url(jsonBytes(map[string]string{"alg": "HS256", "typ": "JWT"}))
	body := base64Url(jsonBytes(payload))
	mac := hmac.New(sha256.New, []byte(SECRET))
	mac.Write([]byte(header + "." + body))
	signature := base64Url(mac.Sum(nil))
	return header + "." + body + "." + signature
}

func jsonBytes(v interface{}) []byte {
	b, _ := json.Marshal(v)
	return b
}

func generateToken() string {
	bytes := make([]byte, 32)
	rand.Read(bytes)
	return hex.EncodeToString(bytes)
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/oauth/authorize", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		clientID := r.URL.Query().Get("client_id")
		if clientID == "" {
			w.WriteHeader(http.StatusBadRequest)
			json.NewEncoder(w).Encode(map[string]string{"error": "Missing client_id"})
			return
		}
		code := generateToken()[:32]
		authCodes[code] = map[string]interface{}{"client_id": clientID}
		json.NewEncoder(w).Encode(map[string]string{"code": code})
	})

	http.HandleFunc("/oauth/token", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "POST" {
			http.NotFound(w, r)
			return
		}
		var body struct {
			GrantType    string `json:"grant_type"`
			Code         string `json:"code"`
			ClientID     string `json:"client_id"`
			RefreshToken string `json:"refresh_token"`
		}
		json.NewDecoder(r.Body).Decode(&body)
		switch body.GrantType {
		case "authorization_code":
			authCode, ok := authCodes[body.Code]
			if !ok || authCode["client_id"] != body.ClientID {
				w.WriteHeader(http.StatusBadRequest)
				json.NewEncoder(w).Encode(map[string]string{"error": "Invalid code"})
				return
			}
			accessToken := createToken(map[string]interface{}{"sub": "user123", "client_id": body.ClientID, "iat": time.Now().Unix(), "exp": time.Now().Unix() + 3600})
			refToken := generateToken()
			refreshTokens[refToken] = map[string]interface{}{"client_id": body.ClientID, "sub": "user123"}
			delete(authCodes, body.Code)
			json.NewEncoder(w).Encode(map[string]interface{}{"access_token": accessToken, "refresh_token": refToken, "token_type": "Bearer", "expires_in": 3600})
		case "refresh_token":
			stored, ok := refreshTokens[body.RefreshToken]
			if !ok {
				w.WriteHeader(http.StatusBadRequest)
				json.NewEncoder(w).Encode(map[string]string{"error": "Invalid refresh token"})
				return
			}
			newAccess := createToken(map[string]interface{}{"sub": stored["sub"], "client_id": stored["client_id"], "iat": time.Now().Unix(), "exp": time.Now().Unix() + 3600})
			newRef := generateToken()
			delete(refreshTokens, body.RefreshToken)
			refreshTokens[newRef] = stored
			json.NewEncoder(w).Encode(map[string]interface{}{"access_token": newAccess, "refresh_token": newRef, "token_type": "Bearer", "expires_in": 3600})
		default:
			w.WriteHeader(http.StatusBadRequest)
			json.NewEncoder(w).Encode(map[string]string{"error": "Unsupported grant_type"})
		}
	})

	http.ListenAndServe(":"+port, nil)
}
